INSERT INTO products (id, shop_id, category_id, sku, name, brand, short_desc, description, price, old_price, discount_percent, stock, sold_count, rating_avg, rating_count, badge, support_custom, switch_type, actuation_force, pin_type, layout, mount_type) VALUES
                                                                                                                                                                                                                                                                   (1, 1, 1, 'KH-TF60-AL', 'Kit Tofu60 2.0 Aluminium — Hotswap, gasket mount, foam sẵn', 'KBDfans', 'Tofu60 2.0 giữ nguyên khối nhôm CNC đặc trưng nhưng chuyển sang gasket mount/top mount linh hoạt, kèm sẵn 3 lớp foam.', 'PCB hotswap 5 chân hỗ trợ QMK/VIA, đèn south-facing không cấn keycap Cherry profile, tạ đáy đồng thau sắc nét.', 2690000, 3280000, 18, 38, 1200, 4.9, 218, '-18%', 1, NULL, NULL, '5-pin', '60%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (4, 5, 1, 'KH-Q1-PRO', 'Kit Keychron Q1 Pro QMK/VIA — Wireless, knob, hotswap, ANSI', 'Keychron', 'Kit nhôm nguyên khối CNC 6063 layout 75% có núm xoay, kết nối Bluetooth 5.1 & Type-C.', 'Cấu trúc Double-Gasket mount cho độ nhún êm ái, mạch hotswap 5-pin hỗ trợ keymap trực tiếp trên trình duyệt qua VIA.', 4290000, 4790000, 10, 24, 2100, 4.8, 310, '-10%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (8, 6, 1, 'KH-M1W-V3', 'Kit Monsgeek M1W V3 Nhôm CNC — 3 Mode Wireless, Hotswap', 'Monsgeek', 'Kit nhôm 75% 3 chế độ kết nối có núm xoay âm lượng, pin 6000mAh bền bỉ.', 'Lựa chọn hàng đầu phân khúc 2 triệu với vỏ nhôm anodized mịn màng, kèm sẵn tấm lót IXPE và PET tạo âm thocky.', 2150000, 2490000, 14, 40, 1540, 4.8, 198, '-14%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (9, 16, 1, 'KH-NEO65-CU', 'Kit Neo65 Custom — Nhôm CNC, Tri-mode Hotswap, Tạ đồng', 'Qwertykeys', 'Kit 65% quốc dân từ nhà Qwertykeys với thiết kế không ốc vít và 2 kiểu mount (Gasket/O-ring).', 'Mạch PCB Hotswap 5-pin không flex-cut giúp âm gõ đầy đặn, kết nối cáp từ tính Daughterboard cực kỳ tiện lợi khi tháo lắp.', 2850000, 3100000, 8, 22, 980, 5.0, 164, 'Hot', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (10, 16, 1, 'KH-NEO80-TKL', 'Kit Neo80 TKL — Ball-catch tháo lắp nhanh, Gasket/O-ring', 'Qwertykeys', 'Kit TKL 80% cao cấp với cơ chế ngàm bi tháo vỏ trong 2 giây không cần tua vít.', 'Hỗ trợ đầy đủ layout ANSI, PCB 1.6mm non-flex cut cho âm thanh clacky/thocky chuẩn mực, tạ đáy thép gương.', 3890000, 4200000, 7, 15, 640, 5.0, 112, 'Mới', 1, NULL, NULL, '5-pin', 'TKL', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (11, 15, 1, 'KH-ZOOM75-EE', 'Kit Zoom75 Essential Edition — Màn hình LCD, Tri-mode', 'Meletrix', 'Kit 75% nổi tiếng với module màn hình LCD góc phải và 12 màu vỏ tĩnh điện/anodized.', 'Tích hợp mạch không dây 3 chế độ, kèm sẵn bộ WS Stupid Stabilizer và đầy đủ foam Poron chính hãng Wuque Studio.', 4650000, 5100000, 9, 18, 820, 4.9, 145, '-9%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (12, 15, 1, 'KH-ZOOM65-V3', 'Kit Zoom65 V3 — Hệ thống 6 kiểu Mount, Nhôm CNC', 'Meletrix', 'Thế hệ thứ 3 của dòng Zoom65 với hệ thống lá nhíp lò xo và ốc nam châm hiện đại.', 'Cho phép người chơi tùy biến cảm giác gõ từ cứng chắc đến nhún mềm chỉ trong vài phút.', 4350000, 0, 0, 20, 510, 4.9, 88, 'Mới', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (13, 16, 1, 'KH-QK75N-TRI', 'Kit QK75N Tri-mode — Màn hình phụ & Núm xoay cơ khí', 'Qwertykeys', 'Sự kết hợp hoàn hảo giữa núm xoay tactile và màn hình hiển thị thông số pin/gif.', 'Khung nhôm CNC 6063 dày dặn, nặng hơn 2kg sau khi build, cho độ đầm tuyệt đối trên bàn làm việc.', 4950000, 5400000, 8, 12, 430, 5.0, 76, '-8%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (14, 27, 1, 'KH-MODE-ENV', 'Kit Mode Envoy 65% — Lattice Block Mount độc quyền', 'Mode', 'Kit 65% thiết kế tối giản sang trọng từ Mỹ với hệ thống khối đỡ Lattice silicon/nhựa.', 'Cảm giác gõ cực kỳ đồng đều ở mọi vị trí phím, thanh accent bằng gỗ óc chó hoặc đồng thau tinh xảo.', 5450000, 0, 0, 10, 290, 5.0, 54, 'Cao cấp', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (15, 27, 1, 'KH-MODE-SON', 'Kit Mode Sonnet 75% — Đỉnh cao gia công CNC Custom', 'Mode', 'Dòng kit 75% flagship của Mode Designs với đường cong thanh lịch và chất lượng hoàn thiện không tì vết.', 'Hỗ trợ cả Isolated Top Mount và Stack Mount, âm gõ trong trẻo đặc trưng không cần dùng nhiều foam.', 7850000, 8200000, 4, 6, 180, 5.0, 41, 'Flagship', 1, NULL, NULL, '5-pin', '75%', 'Top mount'),
                                                                                                                                                                                                                                                                   (16, 26, 1, 'KH-RAINY75-PR', 'Kit Bàn phím Rainy75 Pro — Nhôm CNC, Tạ gương, Pin 7000mAh', 'WOBKEY', 'Hiện tượng bàn phím nhôm 75% âm mưa rơi (Raindrop sound) cực kỳ bắt tai ngay khi mở hộp.', 'Sở hữu cấu trúc HMX/JWK kèm sẵn 5 lớp foam tiêu âm, kết nối 3 mode độ trễ thấp 2ms cho cả chơi game.', 2590000, 2990000, 13, 45, 2450, 4.9, 412, '-13%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (17, 26, 1, 'KH-BRIDGE75-PL', 'Kit Bridge75 Plus — Tháo mở Ball-catch, Nhôm Anodized 220 Mesh', 'Shortcut Studio', 'Kit nhôm 75% bề mặt xử lý cát 220 mịn như nhung, tháo nắp trên không cần ốc vít.', 'Mạch Hotswap RGB south-facing, pin 8000mAh cho thời lượng sử dụng lên đến hơn 1 tháng.', 2290000, 2650000, 14, 50, 1890, 4.8, 275, '-14%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (18, 26, 1, 'KH-GMK67-KIT', 'Kit Zuoya GMK67 — Nhựa ABS, Gasket mount, Núm xoay, 3 Mode', 'Zuoya', 'Kit quốc dân giá rẻ nhất cho sinh viên bắt đầu tập chơi bàn phím cơ custom.', 'Sẵn plate Polycarbonate, đầy đủ foam Poron và IXPE, hotswap 5-pin nhận mọi loại switch trên thị trường.', 690000, 890000, 22, 110, 4200, 4.7, 680, '-22%', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (19, 26, 1, 'KH-LUCKY65-AL', 'Kit Weikav Lucky65 Nhôm CNC — Layout 65%, 3 Mode Wireless', 'Weikav', 'Kit nhôm nguyên khối 65% có giá chỉ ngang vỏ nhựa, nặng 1.3kg cực đầm.', 'Sơn tĩnh điện và Anodize nhiều màu trẻ trung, mạch hotswap 5 chân hỗ trợ phần mềm keymap riêng.', 1390000, 1690000, 18, 65, 2150, 4.8, 320, '-18%', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (20, 28, 1, 'KH-HI75-ALU', 'Kit Leobog Hi75 Nhôm CNC — Núm xoay vũ trụ, Gasket Mount', 'Leobog', 'Kit 75% nổi tiếng với chất âm thocky nổ bắp rang bơ to rõ nhất trong phân khúc.', 'Plate PP mềm dẻo kết hợp 5 lớp foam sẵn có giúp bất kỳ dòng switch nào gắn vào cũng ra âm trầm ấm.', 1150000, 1450000, 21, 80, 3100, 4.8, 510, '-21%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (21, 13, 1, 'KH-TOFU65-V2', 'Kit Tofu65 2.0 Aluminium — 65% Layout, Bowl Gasket Mount', 'KBDfans', 'Phiên bản có cụm phím mũi tên của huyền thoại Tofu với cấu trúc Bowl silicon gasket.', 'Đi kèm bộ stabilizer cherry screw-in, cáp USB-C bện dù và đầy đủ phụ kiện lắp ráp từ KBDfans.', 2890000, 3450000, 16, 28, 870, 4.9, 134, '-16%', 1, NULL, NULL, '5-pin', '65%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (22, 5, 1, 'KH-Q3-MAX', 'Kit Keychron Q3 Max TKL — 2.4GHz Wireless, QMK/VIA, Knob', 'Keychron', 'Bản nâng cấp TKL thêm kết nối 2.4GHz tần số quét 1000Hz chuyên game và công việc.', 'Sử dụng thêm lớp acoustic foam Latex và PET giúp cải thiện đáng kể âm thanh so với đời Q3 Pro.', 4890000, 5290000, 8, 16, 620, 4.9, 95, '-8%', 1, NULL, NULL, '5-pin', 'TKL', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (23, 3, 1, 'KH-MOD007B-HE', 'Kit Akko MOD007B PC — Mạch Từ tính Hall Effect & Hotswap', 'Akko', 'Kit 75% hỗ trợ Rapid Trigger chuyên trị Valorant/CS2 vừa hỗ trợ switch cơ truyền thống.', 'Vỏ Polycarbonate dày dặn xuyên LED RGB rực rỡ, kết nối không dây đa thiết bị.', 2490000, 2890000, 14, 34, 940, 4.8, 156, '-14%', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (24, 10, 1, 'KH-CYCLE7-TKL', 'Kit TKD Cycle7 — 70% FRL TKL, Equalz Gasket/O-ring', 'TKD', 'Layout 70% độc đáo lược bỏ hàng F-row nhưng giữ nguyên cụm điều hướng và phím mũi tên.', 'Bề mặt phủ Coat siêu mịn chống bám vân tay, đi kèm túi đựng chống sốc cao cấp.', 3950000, 0, 0, 11, 380, 5.0, 68, 'Giới hạn', 1, NULL, NULL, '5-pin', '75%', 'Gasket mount'),
                                                                                                                                                                                                                                                                   (25, 1, 1, 'KH-BAKENEKO60', 'Kit Bakeneko60 CNC — O-ring Gummy Mount, Clacky Sound', 'CannonKeys', 'Kit 60% sử dụng vòng cao su O-ring 50A bao quanh mạch và plate cho âm thanh cổ điển.', 'Lắp ráp chỉ mất 5 phút không cần bắt ốc giữa plate và vỏ, cực kỳ phù hợp với switch Linear/Tactile.', 2390000, 2750000, 13, 19, 520, 4.8, 84, '-13%', 1, NULL, NULL, '5-pin', '60%', 'O-ring mount');
INSERT INTO products (id, shop_id, category_id, sku, name, brand, short_desc, description, price, old_price, discount_percent, stock, sold_count, rating_avg, rating_count, badge, support_custom, switch_type, actuation_force, pin_type, layout, mount_type) VALUES
                                                                                                                                                                                                                                                                   (2, 2, 2, 'SW-OIL-70', 'Switch Gateron Oil King — Linear 55g (Bịch 70 nút)', 'Gateron', 'Switch Linear cao cấp đã được pre-lube mượt từ nhà máy, âm trầm đục sâu.', 'Gateron Oil King nổi tiếng với housing Nylon/Ink đen tuyền, lò xo mạ đen dài 20mm cho cảm giác nhấn đầm và trả phím nhanh.', 890000, 990000, 10, 120, 2430, 4.9, 345, '-10%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (5, 3, 2, 'SW-AKKO-CY', 'Switch Akko Cream Yellow V3 Pro — Linear 50g (Hộp 45 nút)', 'Akko', 'Switch quốc dân cho âm thanh clacky/thocky rõ nét, stem POM chống bụi.', 'Phiên bản nâng cấp V3 Pro với chân tiếp xúc hợp kim đồng bền bỉ, lò xo 50g dễ làm quen cho cả gõ văn bản và chơi game.', 320000, 420000, 24, 260, 4800, 4.8, 620, '-24%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (26, 9, 2, 'SW-HMX-XH70', 'Switch HMX Xinhai — Linear 52g, Lube sẵn (Bịch 70 nút)', 'HMX', 'Dòng switch HMX làm mưa làm gió với độ mượt hoàn hảo và âm bottom-out đanh gọn.', 'Khuôn đúc độ chính xác cực cao giúp stem không hề rung lắc, lớp factory lube đều tăm tắp dùng ngay không cần lube lại.', 540000, 620000, 13, 150, 1920, 4.9, 280, '-13%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (27, 1, 2, 'SW-BOBA-U4T', 'Switch Gazzew Boba U4T Thocky — Tactile 62g (Bịch 70 nút)', 'Gazzew', 'Ông vua của dòng switch Tactile với khấc phản hồi tròn đầy và âm thanh trầm hùng.', 'Sử dụng nhựa độc quyền của Gazzew cùng lò xo Hàn Quốc chống tiếng ping kim loại tuyệt đối.', 980000, 1100000, 11, 74, 1650, 5.0, 240, '-11%', 1, 'Tactile', 'Trên 55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (28, 18, 2, 'SW-INK-BLK2', 'Switch Gateron Ink Black V2 — Linear 60g (Bịch 70 nút)', 'Gateron', 'Dòng switch vỏ khói huyền thoại dành cho người thích cảm giác gõ đầm tay và âm trầm.', 'Sau khi được lube Krytox 205g0 và gắn film Deskeys, Ink Black V2 cho ra chất âm sâu lắng bậc nhất.', 1150000, 1290000, 11, 58, 1120, 4.9, 175, '-11%', 1, 'Linear', 'Trên 55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (29, 23, 2, 'SW-CHR-MX2A', 'Switch Cherry MX2A Black — Linear 60g, Lò xo Barrel (70 nút)', 'Cherry', 'Bản cải tiến toàn diện của Cherry MX Black sản xuất tại Đức với rãnh trượt đánh bóng kim cương.', 'Độ bền 100 triệu lần nhấn, âm gõ scratchy đặc trưng được làm mượt hơn nhờ mỡ bôi trơn Krytox từ nhà máy.', 720000, 820000, 12, 95, 1340, 4.8, 190, '-12%', 1, 'Linear', 'Trên 55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (30, 15, 2, 'SW-WS-MORD', 'Switch Wuque Studio WS Morandi — Linear 53g, POM Stem (70 nút)', 'Wuque Studio', 'Switch Linear âm trầm đục như đá cuội (Marbly sound) kèm bộ tản sáng LED tháo rời.', 'Stem UPE kết hợp đáy POM tự bôi trơn càng gõ càng mượt, cực kỳ hợp với các dòng kit có foam.', 790000, 890000, 11, 82, 1480, 4.9, 210, '-11%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (31, 9, 2, 'SW-VTX-V1', 'Switch Vertex V1 — Linear 52g, Housing JWK đen tuyền (70 nút)', 'Vertex', 'Kẻ thách thức Gateron Oil King với mức giá chỉ bằng một nửa nhưng độ mượt tương đương.', 'Hành trình 4.0mm trọn vẹn không cắt ngắn, âm trầm ấm dễ chịu khi gõ thời gian dài.', 450000, 520000, 13, 140, 2100, 4.8, 310, '-13%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (32, 19, 2, 'SW-HMX-CHS', 'Switch HMX Cheese — Linear 45g Nhẹ nhàng, Âm Marbly (70 nút)', 'HMX', 'Switch phối màu phô mai vàng cam bắt mắt, lực nhấn nhẹ 45g không gây mỏi ngón tay.', 'Lò xo đơn 22mm KOS cho độ nảy cực kỳ linh hoạt, phù hợp cả gõ code lẫn chơi game.', 490000, 0, 0, 110, 1280, 4.9, 185, 'Mới', 1, 'Linear', 'Dưới 45g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (33, 19, 2, 'SW-HMX-CLD', 'Switch HMX Cloud — Linear 42g Siêu nhẹ, Clacky (70 nút)', 'HMX', 'Lực nhấn 42g nhẹ như mây cùng âm thanh gõ giòn tan trong trẻo.', 'Stem LY siêu trơn giảm ma sát tối đa ngay từ lần nhấn đầu tiên.', 510000, 580000, 12, 90, 960, 4.8, 140, '-12%', 1, 'Linear', 'Dưới 45g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (34, 18, 2, 'SW-GAT-BBK', 'Switch Gateron Baby Kangaroo 2.0 — Tactile 59g (Bịch 70 nút)', 'Gateron', 'Dòng switch Tactile khấc sớm đầu hành trình với lò xo 2 tầng 22mm cực nảy.', 'Vỏ trên trong suốt giúp đèn RGB tỏa sáng rực rỡ, âm gõ vang và rõ nét.', 920000, 1050000, 12, 64, 890, 4.9, 130, '-12%', 1, 'Tactile', 'Trên 55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (35, 18, 2, 'SW-GAT-MLK', 'Switch Gateron Milky Yellow Pro — Linear 50g Quốc dân (70 nút)', 'Gateron', 'Huyền thoại switch giá rẻ cho chất âm trầm ấm dễ nghe nhất mọi thời đại.', 'Bản Pro đã được nhà máy Gateron bôi trơn sẵn lò xo và stem, mua về cắm vào dùng ngay.', 380000, 450000, 16, 220, 3900, 4.9, 540, '-16%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (36, 9, 2, 'SW-KTT-KW3', 'Switch KTT Kang White V3 — Linear 43g Giá sinh viên (70 nút)', 'KTT', 'Switch màu trắng tinh khôi xuyên LED tốt, lực nhấn nhẹ nhàng dưới 45g.', 'Khi được lube thêm Krytox 205g0 tại xưởng sẽ lột xác hoàn toàn với âm thanh vượt xa tầm giá.', 290000, 350000, 17, 180, 2750, 4.7, 390, '-17%', 1, 'Linear', 'Dưới 45g', '3-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (37, 3, 2, 'SW-AKKO-CB', 'Switch Akko V3 Cream Blue Pro — Tactile 45g (Hộp 45 nút)', 'Akko', 'Switch Tactile khấc vừa phải không gây mỏi tay, âm thanh clacky vui tai.', 'Hành trình 3.3mm giúp tốc độ nhận phím nhanh hơn chuẩn truyền thống.', 320000, 400000, 20, 195, 2300, 4.8, 320, '-20%', 1, 'Tactile', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (38, 3, 2, 'SW-AKKO-PN', 'Switch Akko Rosewood / Piano Pro — Linear 45g Thocky (45 nút)', 'Akko', 'Thiết kế chuyên biệt để tạo ra tần số âm thanh trầm ấm như phím đàn gỗ.', 'Chân 5-pin cắm cực chắc trên cả những bàn phím không dùng plate.', 360000, 440000, 18, 130, 1520, 4.9, 215, '-18%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (39, 28, 2, 'SW-LBG-GW4', 'Switch Leobog Graywood V4 — Linear 40g Siêu mượt (Bịch 70 nút)', 'Leobog', 'Switch nổ bắp rang bơ giá hạt dẻ được săn đón nhiều nhất cho các bản build 1-2 triệu.', 'Cấu trúc tản sáng LED đi kèm giúp hiệu ứng đèn đều và đẹp hơn.', 310000, 390000, 21, 210, 3400, 4.8, 480, '-21%', 1, 'Linear', 'Dưới 45g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (40, 28, 2, 'SW-LBG-RPR', 'Switch Leobog Reaper — Linear 45g, Stem POM (Bịch 70 nút)', 'Leobog', 'Cặp bài trùng hoàn hảo đi kèm kit Leobog Hi75 và Aula F75.', 'Cho cảm giác chạm đáy đanh chắc, độ rung lắc stem gần như bằng không.', 390000, 460000, 15, 160, 2600, 4.9, 360, '-15%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (41, 21, 2, 'SW-OUT-PCH3', 'Switch Outemu Silent Peach V3 — Linear Không Tiếng Động (70 nút)', 'Outemu', 'Giải pháp im lặng tuyệt đối khi gõ đêm hoặc làm việc trong phòng họp.', 'Đệm giảm chấn silicon cải tiến V3 không gây cảm giác nhũn tay như các dòng switch silent đời cũ.', 350000, 420000, 17, 145, 1780, 4.8, 250, '-17%', 1, 'Linear', 'Dưới 45g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (42, 21, 2, 'SW-OUT-LMN3', 'Switch Outemu Silent Lime V3 — Tactile Im lặng 45g (70 nút)', 'Outemu', 'Vừa giữ được khấc phản hồi xúc giác Tactile vừa triệt tiêu hoàn toàn tiếng ồn.', 'Đã được pre-lube rãnh trượt từ nhà máy, chân 5-pin vững chãi.', 360000, 430000, 16, 120, 1320, 4.8, 180, '-16%', 1, 'Tactile', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (43, 9, 2, 'SW-KLH-JADE', 'Switch Kailh Box Jade — Clicky 50g Thanh Click Bar (70 nút)', 'Kailh', 'Switch Clicky cho tiếng tách đanh vang và khấc nhấn cực kỳ rõ rệt nhờ cơ chế Click Bar.', 'Thiết kế hộp Box chống bụi và kháng nước chuẩn IP56 bảo vệ tiếp điểm.', 680000, 760000, 11, 70, 920, 4.9, 140, '-11%', 1, 'Clicky', '45-55g', '3-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (44, 9, 2, 'SW-KLH-WHT2', 'Switch Kailh Box White V2 — Clicky 45g Nhẹ nhàng (70 nút)', 'Kailh', 'Tiếng click thanh mảnh như tiếng bấm bút bi, lò xo dài mạ vàng trả phím dứt khoát.', 'Chân 5-pin thế hệ V2 tương thích hoàn hảo với mọi mạch hotswap hiện đại.', 650000, 750000, 13, 85, 1050, 4.8, 160, '-13%', 1, 'Clicky', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (45, 23, 2, 'SW-CHR-BRN2', 'Switch Cherry MX2A Brown — Tactile 55g Chuẩn Đức (Bịch 70 nút)', 'Cherry', 'Switch Tactile nhẹ nhàng kinh điển cho lập trình viên gõ hàng chục ngàn dòng code mỗi ngày.', 'Tuổi thọ 100 triệu lần nhấn với tiếp điểm vàng Gold Crosspoint độc quyền.', 720000, 820000, 12, 90, 1180, 4.8, 170, '-12%', 1, 'Tactile', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (46, 2, 2, 'SW-TTC-GLDP', 'Switch TTC Gold Pink V2 — Linear 37g Siêu nhẹ (Bịch 70 nút)', 'TTC', 'Dòng switch cao cấp cực nhẹ dành cho người gõ lướt hoặc cổ tay yếu.', 'Chân tiếp xúc mạ bạc chống oxy hóa, lò xo mạ vàng chống rỉ sét tuyệt đối.', 950000, 1100000, 14, 50, 680, 4.9, 95, '-14%', 1, 'Linear', 'Dưới 45g', '3-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (47, 10, 2, 'SW-BSUN-RAW', 'Switch BSUN Raw Linear — 50g Clacky Chuẩn Audiophile (70 nút)', 'BSUN', 'Switch yêu thích của các builder chơi phím không foam (foam-less build).', 'Âm thanh chạm đáy giòn, tròn tiếng và cực kỳ sạch sẽ không tạp âm.', 840000, 0, 0, 60, 540, 4.9, 82, 'Mới', 1, 'Linear', '45-55g', '5-pin', NULL, NULL),
                                                                                                                                                                                                                                                                   (48, 7, 2, 'SW-DRK-POM', 'Switch Durock POM Piano — Full POM Linear 55g (Bịch 70 nút)', 'Durock', 'Toàn bộ vỏ và stem đều làm từ nhựa POM tự bôi trơn cho âm thanh trầm ấm đặc trưng.', 'Đi kèm lò xo mạ vàng Hàn Quốc hạn chế tối đa tiếng vang lò xo.', 990000, 1150000, 14, 45, 610, 4.9, 90, '-14%', 1, 'Linear', '45-55g', '5-pin', NULL, NULL);
