                                                                                                                                                                                                                                                                   (3, 4, 3, 'KC-GMK-OLV', 'Keycap GMK Olivia++ Cherry profile — Bộ Base 137 phím', 'GMK', 'Bộ keycap ABS doubleshot cao cấp tông màu hồng Rose Gold & Đen kinh điển.', 'GMK Olivia++ sản xuất tại Đức với ký tự doubleshot sắc nét, tương thích mọi layout từ 60% đến Fullsize.', 4150000, 4500000, 8, 15, 286, 5.0, 62, 'Cao cấp', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (7, 3, 3, 'KC-AKKO-BP', 'Keycap Akko Black & Pink ASA profile — 158 phím PBT', 'Akko', 'Keycap nhựa PBT Double-Shot dày dặn, ASA profile bầu bĩnh dễ làm quen.', 'Bộ nút phím 158 nút cân được hầu hết các chuẩn layout trên thị trường, không bị bóng nhám sau thời gian dài.', 690000, 890000, 22, 85, 2800, 4.8, 390, '-22%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (49, 4, 3, 'KC-GMK-SAM', 'Keycap GMK Red Samurai Cherry profile — Base TKL/65%', 'GMK', 'Phối màu Đỏ rượu vang kết hợp chữ Vàng kim và sub-legend Hiragana đậm chất Nhật Bản.', 'Nhựa ABS nguyên sinh dày 1.5mm cho âm gõ đanh gọn và màu sắc rực rỡ không đối thủ.', 3450000, 3890000, 11, 18, 410, 4.9, 78, '-11%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (50, 4, 3, 'KC-GMK-WOB', 'Keycap GMK White on Black (WoB) Cherry — Base 140 phím', 'GMK', 'Bộ keycap Đen chữ Trắng tối giản dễ phối với mọi màu vỏ bàn phím từ Bạc, Đen đến Đỏ, Xanh.', 'Ký tự CYL Cherry huyền thoại sắc sảo đến từng chi tiết nhỏ.', 3150000, 0, 0, 22, 650, 5.0, 115, 'Bán chạy', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (51, 24, 3, 'KC-PBF-WOB', 'Keycap PBTfans WoB Double-shot PBT — Cherry profile 148 phím', 'PBTfans', 'Giải pháp thay thế GMK WoB bằng chất liệu nhựa PBT nhám mịn không bao giờ bị bóng phím.', 'Đựng trong khay nhựa 3 tầng sang trọng từ KBDfans, hỗ trợ mọi layout.', 1850000, 2100000, 12, 35, 920, 4.9, 165, '-12%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (52, 24, 3, 'KC-PBF-KLN', 'Keycap PBTfans Klein Blue — Cherry profile Semi-transparent', 'PBTfans', 'Tông màu xanh Klein Blue kết hợp lớp vỏ bán trong suốt độc đáo.', 'Ký tự ABS doubleshot siêu nét, dày 1.6mm tạo âm trầm ấm khi lắp trên kit nhôm.', 2150000, 2450000, 12, 24, 540, 4.9, 92, '-12%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (53, 29, 3, 'KC-OSM-TSK', 'Keycap Osume Tsukimi — Cherry profile PBT, Tone Pastel Trăng Rằm', 'Osume', 'Font chữ nhỏ nhắn tinh tế đặc trưng của thương hiệu Osume Canada kèm bộ phím Novelty thỏ ngọc.', 'Bề mặt PBT mịn như lụa, cực kỳ được ưa chuộng bởi các góc setup tối giản.', 2250000, 0, 0, 16, 480, 5.0, 88, 'Hot', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (54, 29, 3, 'KC-OSM-MTC', 'Keycap Osume Matcha — Cherry profile PBT Xanh Trà Xanh', 'Osume', 'Phối màu xanh trà xanh dịu mắt kết hợp màu kem sữa nhẹ nhàng.', 'Độ dày 1.6mm chuẩn mực, không một phím dài nào bị cong vênh.', 2190000, 2390000, 8, 20, 510, 4.9, 94, '-8%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (55, 24, 3, 'KC-SHP-BGE', 'Keycap Shenpo Classic Beige Retro — Cherry PBT Dye-sub 145 phím', 'Shenpo', 'Tái hiện vẻ đẹp hoài cổ của những chiếc bàn phím IBM/Cherry thập niên 90.', 'Nhựa PBT dày 1.7mm đúc cực khít, thanh Space thẳng tắp không cần nắn.', 790000, 950000, 17, 60, 1640, 4.9, 245, '-17%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (56, 4, 3, 'KC-JTK-NSK', 'Keycap JTK Night Sakura — ABS Doubleshot/Tripleshot Cherry', 'JTK', 'Lấy cảm hứng từ hoa anh đào nở trong đêm với tông xám đen và hồng phấn.', 'Đi kèm hộp đựng keycap JTK Max chính hãng cực kỳ chắc chắn.', 2450000, 2790000, 12, 14, 320, 4.9, 58, '-12%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (57, 4, 3, 'KC-DMK-CYB', 'Keycap Domikey Cyberpunk SA Profile — ABS Doubleshot Cao Vút', 'Domikey', 'Profile SA cao cổ điển tạo ra tiếng gõ vang rền đặc trưng không thể trộn lẫn.', 'Phối màu tím neon và xanh cyan nổi bật cho góc gaming.', 1950000, 2250000, 13, 19, 390, 4.8, 64, '-13%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (58, 26, 3, 'KC-AIF-WOB', 'Keycap Aifei WoB / BoW Cherry profile — ABS Doubleshot 172 phím', 'Aifei', 'Bộ keycap quốc dân giá rẻ dưới 500k nhưng chất lượng ký tự tiệm cận phân khúc tiền triệu.', 'Đầy đủ 172 nút lắp vừa mọi layout dị từ Alice, 60%, 65%, 75% đến Fullsize.', 450000, 590000, 24, 150, 3800, 4.8, 520, '-24%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (59, 26, 3, 'KC-CMK-DRC', 'Keycap CMK Dracula Clone — Cherry PBT Double-shot 173 phím', 'CMK', 'Phối màu theo theme code Dracula nổi tiếng trên VSCode và IntelliJ IDEA.', 'Ký tự nhiều màu nổi bật trên nền xám đậm, nhựa PBT dày 1.5mm.', 550000, 690000, 20, 95, 2150, 4.8, 310, '-20%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (60, 24, 3, 'KC-GJ-APL', 'Keycap Ghost Judges Apollo — Cherry PBT Double-shot 168 phím', 'Ghost Judges', 'Lấy cảm hứng từ tàu vũ trụ Apollo với tông màu Xám, Trắng và Xanh vũ trụ.', 'Được sản xuất bởi KPrepublic với chất lượng khuôn đúc sắc nét, không ba via.', 950000, 1150000, 17, 42, 870, 4.9, 135, '-17%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (61, 3, 3, 'KC-AKKO-MCW', 'Keycap Akko Macaw Cherry profile — PBT Double-shot 157 phím', 'Akko', 'Phối màu Xanh dương - Vàng tươi năng động lấy cảm hứng từ loài vẹt Macaw Nam Mỹ.', 'Kèm hộp nhựa bảo quản tiện lợi, đầy đủ phím Shift ngắn 1.75u cho layout 65%/75%.', 690000, 850000, 19, 75, 1920, 4.8, 270, '-19%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (62, 3, 3, 'KC-AKKO-WVE', 'Keycap Akko Wave ASA profile — PBT Double-shot Xanh Sóng Biển', 'Akko', 'Tông màu xanh đại dương kết hợp ký tự xanh lá neon nổi bật.', 'Chiều cao ASA kết hợp ưu điểm âm thanh của SA và sự thoải mái của OEM.', 720000, 890000, 19, 68, 1450, 4.8, 210, '-19%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (63, 6, 3, 'KC-MGS-CHG', 'Keycap Monsgeek Chicago Cherry profile — 152 phím PBT', 'Monsgeek', 'Tông màu Xám - Đỏ Đô thanh lịch phù hợp cho không gian làm việc chuyên nghiệp.', 'Nhựa PBT nguyên chất chống bám mồ hôi tay hiệu quả.', 620000, 750000, 17, 80, 1120, 4.7, 160, '-17%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (64, 29, 3, 'KC-NPB-NOEL', 'Keycap NicePBT Noel — Cherry profile Pastel Hồng Xanh Băng', 'CannonKeys', 'Bộ keycap màu pastel ngọt ngào từ CannonKeys với ký tự in nhiệt Dye-sub 5 mặt.', 'Hỗ trợ cả phím Space rời cho các dòng bàn phím Split/Alice.', 1650000, 1890000, 13, 25, 430, 4.9, 72, '-13%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (65, 26, 3, 'KC-XVX-PUD', 'Keycap XVX Pudding V2 OEM profile — Xuyên LED RGB Rực Rỡ', 'XVX', 'Thiết kế 2 lớp sữa trong suốt ở thân dưới giúp ánh sáng đèn RGB lan tỏa 360 độ.', 'Bề mặt trên vẫn giữ chất liệu PBT nhám bền bỉ.', 320000, 420000, 24, 160, 2900, 4.7, 410, '-24%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (66, 26, 3, 'KC-GRAD-SIDE', 'Keycap Gradient Xám Đen In Sườn (Side-printed) OEM Xuyên LED', 'OEM', 'Ký tự khắc laser ở mặt trước nút phím giúp mặt trên phẳng mịn hiện đại.', 'Cực kỳ hợp với các dòng mạch có đèn LED hướng nam (South-facing LED).', 390000, 490000, 20, 130, 2400, 4.8, 340, '-20%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (67, 4, 3, 'KC-GMK-BOT2', 'Keycap GMK Botanical 2 — Cherry profile Xanh Thực Vật', 'GMK', 'Tông màu xanh lá cây rừng nhiệt đới thư giãn nhất cho bàn làm việc.', 'Sản xuất tại Đức bằng nhựa ABS cao cấp.', 3850000, 4200000, 8, 12, 230, 5.0, 48, '-8%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (68, 24, 3, 'KC-EPBT-9009', 'Keycap ePBT 9009 Classic — Cherry PBT Dye-sub Đỏ Xanh Pastel', 'ePBT', 'Phối màu Retro 9009 bất hủ với phím Enter đỏ và Esc xanh rêu.', 'Độ bền ký tự vĩnh viễn không phai mờ theo năm tháng.', 1750000, 1990000, 12, 30, 670, 4.9, 105, '-12%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (69, 13, 3, 'KC-KBD-CLR', 'Keycap KBDfans Clear 2048 — Polycarbonate Trong Suốt Cherry', 'KBDfans', 'Bộ keycap trong suốt như pha lê in ký tự biểu tượng hệ điều hành Mac cổ điển.', 'Kết hợp tuyệt đẹp với các dòng kit vỏ PC hoặc Acrylic.', 1450000, 1690000, 14, 28, 490, 4.8, 76, '-14%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (70, 5, 3, 'KC-KCH-OSA', 'Keycap Keychron OSA PBT Double-shot — Đen Xám Cam', 'Keychron', 'Bộ keycap tháo máy dòng Keychron Q-Pro với profile OSA bo tròn công thái học.', 'Nhựa PBT chống dầu mỡ, gõ êm và đầm tay.', 590000, 720000, 18, 65, 880, 4.8, 125, '-18%', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL),
                                                                                                                                                                                                                                                                   (71, 17, 3, 'KC-ART-KOI', 'Keycap Artisan Cá Chép Hóa Rồng — Đúc Thủ Công Epoxy Resin', 'Artisan Mộc', 'Nút phím ESC 1u chế tác thủ công từng lớp nhựa Resin trong suốt 3D sống động.', 'Mỗi nút phím là một tác phẩm độc bản được đánh bóng tay 7 bước.', 650000, 790000, 18, 25, 540, 5.0, 92, 'Thủ công', 0, NULL, NULL, NULL, '60%, 75%, TKL', NULL);
INSERT INTO products (id, shop_id, category_id, sku, name, brand, short_desc, description, price, old_price, discount_percent, stock, sold_count, rating_avg, rating_count, badge, support_custom, switch_type, actuation_force, pin_type, layout, mount_type) VALUES
                                                                                                                                                                                                                                                                   (6, 2, 4, 'ST-DRV2', 'Stabilizer Durock V2 PCB-mount Screw-in — Đã lube sẵn', 'Durock', 'Bộ stab screw-in tiêu chuẩn vàng chống lọc xọc, đã được thợ lube Krytox 205g0.', 'Bộ sản phẩm gồm 4 thanh 2u và 1 thanh 6.25u/7u, ốc vít mạ vàng kèm long đền chống chập mạch.', 420000, 480000, 13, 54, 1760, 4.9, 290, '-13%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (72, 25, 4, 'ST-TX-AP4', 'Stabilizer TX AP v4 (Almost Perfect) — PCB Clip-in 1.6mm/1.2mm', 'TX Keyboard', 'Dòng stab đỉnh cao nhất hiện nay với lõi TPU đúc kép triệt tiêu hoàn toàn tiếng lọc xọc.', 'Chỉ cần bôi một lớp mỏng Krytox 205g0 là êm ru mà không cần làm Holee mod.', 450000, 510000, 12, 70, 2150, 5.0, 340, 'Bán chạy', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (73, 25, 4, 'ST-STAE-V21', 'Stabilizer AEBoards Staebies V2.1 — POM/Nylon Screw-in', 'AEBoards', 'Dung sai khuôn đúc cực kỳ khít giúp thanh thép wire không có độ rơ ngang.', 'Bản V2.1 đã khắc phục hoàn toàn hiện tượng kẹt stem với mọi bộ keycap GMK.', 520000, 590000, 12, 40, 980, 4.9, 155, '-12%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (74, 15, 4, 'ST-WS-STPD', 'Stabilizer WS Stupid Stab — Đệm Silicon Đúc Sẵn Trong Housing', 'Wuque Studio', 'Thiết kế thông minh lót sẵn dải silicon giảm chấn ngay bên trong lòng housing.', 'Giúp người mới chơi dễ dàng có được phím Space êm ái chỉ sau 5 phút lắp đặt.', 350000, 400000, 13, 85, 1420, 4.9, 210, '-13%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (75, 25, 4, 'ST-C3-EQV3', 'Stabilizer C³ Equalz V3 Screw-in — Kèm trọn bộ墊 Soulmate', 'C3 Equalz', 'Đi kèm sẵn toàn bộ miếng dán đệm PCB, miếng dán wire và ốc vít mạ vàng.', 'Nhiều màu sắc trẻ trung để phối đồng bộ với màu plate và switch.', 410000, 470000, 13, 48, 860, 4.8, 130, '-13%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (76, 18, 4, 'ST-GAT-INK2', 'Stabilizer Gateron Ink V2 Screw-in — Nhựa Ink Đen Khói', 'Gateron', 'Đồng bộ chất liệu và màu sắc với dòng switch Gateron Ink Black V2.', 'Thanh thép mạ đen chống oxy hóa và được nắn thẳng từ nhà máy.', 460000, 520000, 12, 36, 640, 4.8, 95, '-12%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (77, 10, 4, 'ST-OWL-V3', 'Stabilizer Owlab V3 Screw-in — Thanh Wire Thép Nhớ Hình', 'Owlab', 'Sử dụng hợp kim nhớ hình hạn chế cong vênh thanh thép khi tháo lắp keycap mạnh tay.', 'Bộ kit gồm đầy đủ phụ kiện cho layout 60%, 65%, 75% và TKL.', 440000, 0, 0, 32, 720, 4.9, 110, 'Mới', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (78, 23, 4, 'ST-CHR-ORG', 'Stabilizer Cherry Original PCB Clip-in — Chuẩn Cổ Điển Đức', 'Cherry', 'Lựa chọn số 1 của các thợ build phím custom truyền thống khi kết hợp với clip chân.', 'Nhựa Nylon bền bỉ cùng thanh wire chuẩn xác dễ cân chỉnh.', 280000, 340000, 18, 90, 1540, 4.8, 230, '-18%', 1, NULL, NULL, NULL, NULL, 'PCB-mount'),
                                                                                                                                                                                                                                                                   (79, 25, 4, 'ST-TX-PLT', 'Stabilizer TX AP v4 Plate-mount — Dành cho Kit Gắn Plate', 'TX Keyboard', 'Cứu cánh cho các dòng bàn phím dùng stab gắn trên Plate (như GMK67, Keychron V-series).', 'Loại bỏ hoàn toàn tiếng lọc xọc thường gặp trên stab plate-mount rẻ tiền.', 450000, 0, 0, 62, 1180, 5.0, 185, 'Hot', 1, NULL, NULL, NULL, NULL, 'Plate-mount'),
                                                                                                                                                                                                                                                                   (80, 2, 4, 'ST-DRK-PLT', 'Stabilizer Durock Plate-mount Piano — Đã Lube Sẵn Krytox', 'Durock', 'Phối màu Đen Trắng Piano lịch lãm, đã được thợ SwitchHouse cân wire và lube sẵn.', 'Chỉ việc gài vào plate là sử dụng ngay không cần tháo rời.', 260000, 320000, 19, 75, 1690, 4.8, 260, '-19%', 1, NULL, NULL, NULL, NULL, 'Plate-mount');
