                                                                                                                                                                                                                                                                   (81, 12, 5, 'PK-CAB-AVI', 'Cáp Xoắn Custom Coiled Cable — Đầu nối Aviator GX16 Bọc Lưới Techflex', 'Cáp Nghệ Nhân', 'Cáp bàn phím cơ chế tác thủ công 2 lớp lưới Paracord & Techflex giữ form xoắn vĩnh viễn.', 'Lõi đồng nguyên chất bọc chống nhiễu đảm bảo cấp đủ nguồn cho mọi bàn phím RGB.', 480000, 580000, 17, 45, 1340, 4.9, 210, '-17%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (82, 12, 5, 'PK-CAB-LEM', 'Cáp Custom Đầu Nối LEMO Push-Pull Cao Cấp — Dây Mềm Bọc Dù', 'Cáp Nghệ Nhân', 'Đầu nối tự khóa Push-Pull mạ crôm sang trọng lấy cảm hứng từ thiết bị hàng không.', 'Nhiều phối màu đồng bộ với GMK Olivia, Red Samurai, Botanical.', 750000, 890000, 16, 28, 620, 5.0, 98, '-16%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (83, 11, 5, 'PK-LUB-205', 'Mỡ Lube Switch Krytox GPL 205g0 Chính Hãng Chemours (Hũ 5g / 10g)', 'Krytox', 'Tiêu chuẩn vàng để lube switch Linear và Stabilizer, chiết từ thùng nguyên seal Mỹ.', 'Hũ 5g đủ lube từ 120 đến 150 switch kèm tặng cọ lube đầu mảnh.', 190000, 240000, 21, 160, 4100, 5.0, 640, '-21%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (84, 11, 5, 'PK-LUB-105', 'Dầu Lube Lò Xo Krytox GPL 105 Chính Hãng (Lọ Nhỏ Giọt 10ml)', 'Krytox', 'Dầu lỏng chuyên dụng để bag-lube lò xo switch, khử sạch 100% tiếng ping kim loại.', 'Thiết kế đầu nhỏ giọt tiện lợi, chỉ cần 5-7 giọt cho 70 lò xo trong túi zip.', 180000, 220000, 18, 140, 3200, 4.9, 490, '-18%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (85, 11, 5, 'PK-FLM-DSK', 'Switch Film Deskeys (Bịch 120 miếng) — Đệm Cao Su/Poron 0.3mm', 'Deskeys', 'Giúp cố định chặt nắp trên (top housing) của switch, làm âm gõ trầm và tròn tiếng hơn.', 'Co giãn đàn hồi tốt, tái sử dụng được nhiều lần khi mở switch.', 165000, 195000, 15, 110, 2150, 4.9, 320, '-15%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (86, 15, 5, 'PK-PUL-WS', 'Dụng Cụ Nhổ Switch Wuque Studio Titanium Switch Puller', 'Wuque Studio', 'Làm từ hợp kim Titanium đàn hồi cao, mũi vát mỏng dễ kẹp không làm trầy plate nhôm.', 'Thiết kế công thái học giúp nhổ 80 switch liên tục không bị đau lòng bàn tay.', 390000, 450000, 13, 40, 780, 5.0, 125, '-13%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (87, 11, 5, 'PK-OPN-ALU', 'Dụng Cụ Mở Switch Nhôm CNC 2-in-1 (Mở cả chuẩn MX & Kailh)', 'KeebHub', 'Gia công từ nhôm nguyên khối anodized, tách switch trong 1 giây để lube.', 'Tích hợp nam châm giữ cố định hai nửa dụng cụ gọn gàng trên bàn.', 140000, 180000, 22, 95, 1890, 4.8, 280, '-22%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (88, 11, 5, 'PK-STA-LUB', 'Khay Lube Station Acrylic 90 Switch + Giá Đỡ Lò Xo & Stem', 'Lube Station', 'Giúp sắp xếp gọn gàng 90 switch cùng lúc, tăng tốc độ lube lên gấp 2 lần.', 'Kèm chân đế cao su chống trượt và khay đựng mỡ Krytox.', 195000, 250000, 22, 70, 1420, 4.8, 215, '-22%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (89, 22, 5, 'PK-FOM-PRN', 'Bộ Foam Poron Switch Pads + PET Sheet Mod Âm Marbly (90 nút)', 'Plate Foam Việt', 'Miếng dán đệm chân switch bằng Poron Nhật Bản kết hợp tấm PET tạo âm nổ giòn.', 'Cắt laser sẵn lỗ chân switch và lỗ đèn LED cực kỳ chính xác.', 120000, 150000, 20, 180, 2950, 4.9, 430, '-20%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (90, 17, 5, 'PK-WRS-WAL', 'Kê Tay Bàn Phím Gỗ Óc Chó Bắc Mỹ Nguyên Khối (Size 60% / 65% / 75% / TKL)', 'Artisan Mộc', 'Gỗ Óc Chó tự nhiên sấy khô chống cong vênh, phủ dầu lau gỗ Rubio Monocoat an toàn.', 'Độ dốc vát chuẩn góc nghiêng bàn phím cơ giúp cổ tay luôn thẳng thoải mái.', 420000, 520000, 19, 55, 1240, 4.9, 195, '-19%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (91, 13, 5, 'PK-BAG-KBD', 'Túi Đựng Bàn Phím Chống Sốc KBDfans Carrying Case (60% - TKL)', 'KBDfans', 'Vỏ vải Canvas cứng cáp kết hợp lớp lót nhung mềm bảo vệ phím custom khi di chuyển.', 'Đựng vừa các dòng kit nhôm nặng tới 3kg.', 550000, 650000, 15, 38, 860, 4.9, 140, '-15%', 0, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (92, 29, 5, 'PK-DSK-TSK', 'Deskmat Thảm Trải Bàn Khổ Lớn 900x400x4mm Bo Viền Chống Thấm', 'Osume', 'Lớp cao su tự nhiên dày 4mm vừa làm đẹp góc máy vừa giúp tiêu âm cho bàn phím cơ.', 'Bề mặt vải dệt mịn tối ưu cho mắt đọc chuột gaming.', 450000, 550000, 18, 65, 1580, 4.9, 240, '-18%', 0, NULL, NULL, NULL, NULL, NULL);
INSERT INTO products (id, shop_id, category_id, sku, name, brand, short_desc, description, price, old_price, discount_percent, stock, sold_count, rating_avg, rating_count, badge, support_custom, switch_type, actuation_force, pin_type, layout, mount_type) VALUES
                                                                                                                                                                                                                                                                   (93, 2, 6, 'DV-LUBE-70', 'Gói Dịch Vụ Lube & Film 70-90 Switch Bằng Krytox 205g0 & GPL 105', 'SwitchHouse', 'Thợ kỹ thuật tách từng switch, lube housing/stem bằng Krytox 205g0, lube lò xo GPL 105 và gắn film.', 'Bảo hành độ mượt 6 tháng, bàn giao kèm video test âm thanh từng hàng phím.', 450000, 550000, 18, 99, 1850, 5.0, 310, 'Phổ biến', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (94, 2, 6, 'DV-FULL-TUNE', 'Gói Gia Công Trọn Bộ: Lube Switch + Cân Stab + Mod Âm Thanh Thocky', 'SwitchHouse', 'Gói dịch vụ bán chạy nhất tại SwitchHouse bao gồm toàn bộ công đoạn từ A-Z cho 1 chiếc phím.', 'Gồm Lube + Film switch, cân wire & lube Stabilizer, Tape mod, PE foam và kiểm tra thông mạch.', 750000, 900000, 17, 99, 2420, 5.0, 420, 'Bán chạy', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (95, 25, 6, 'DV-STAB-TUNE', 'Gói Dịch Vụ Cân Chỉnh & Lube Stabilizer Chống Lọc Xọc Tuyệt Đối', 'TX Tuning', 'Nắn thẳng thanh thép wire trên mặt kính phẳng, lube Krytox 205g0/XHT-BDZ và căn chỉnh đều 2 bên.', 'Cam kết phím Space, Enter, Shift, Backspace đầm chắc, không một tiếng tích hay lọc xọc.', 250000, 300000, 17, 99, 1640, 5.0, 275, '-17%', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (96, 8, 6, 'DV-DESOLDER', 'Gói Dịch Vụ Rã Hàn Mạch Phím Cơ Cũ & Hàn Thay Switch Mới', 'Hà Nội Keeb', 'Sử dụng súng hút thiếc chân không Hakko FR-301 chuyên dụng, đảm bảo không bong tróc pad đồng.', 'Vệ sinh sạch nhựa thông trên mạch PCB bằng dung dịch chuyên dụng trước khi bàn giao.', 350000, 420000, 17, 99, 980, 4.9, 165, '-17%', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (97, 8, 6, 'DV-MILLMAX', 'Gói Độ Mạch Hàn Thành Hotswap Bằng Chân Đồng Mill-Max 3305 / 7305', 'Hà Nội Keeb', 'Biến mọi mạch hàn (Solder PCB) thành mạch thay nóng Hotswap tiện lợi mà không làm dày mạch.', 'Đã bao gồm 140-180 chân đồng Mill-Max mạ vàng chính hãng nhập từ Mỹ.', 950000, 1100000, 14, 50, 540, 5.0, 92, 'Cao cấp', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (98, 20, 6, 'DV-CERAKOTE', 'Gói Sơn Gốm Cerakote Đổi Màu Vỏ Nhôm Bàn Phím Cơ Custom', 'Cerakote Lab', 'Sơn gốm vũ khí Cerakote nhập khẩu Mỹ siêu bền, chống trầy xước và hóa chất tuyệt đối.', 'Hơn 40 mã màu tùy chọn từ Trắng Stormtrooper, Xám Titanium đến Hồng Pastel.', 1450000, 1700000, 15, 30, 380, 4.9, 64, '-15%', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (99, 22, 6, 'DV-CNC-PLT', 'Gói Cắt CNC Plate Theo File Thiết Kế Riêng (FR4 / POM / PC / Carbon)', 'Plate Foam Việt', 'Nhận file .DXF hoặc cắt theo mẫu của hơn 200 dòng kit custom phổ biến trên thị trường.', 'Gia công chính xác từng milimet bằng máy CNC công nghiệp, bo mịn các cạnh ngàm switch.', 380000, 450000, 16, 80, 890, 4.9, 145, '-16%', 1, NULL, NULL, NULL, NULL, NULL),
                                                                                                                                                                                                                                                                   (100, 30, 6, 'DV-REPAIR-PCB', 'Gói Cứu Mạch Liệt Phím, Câu Dây Đồng & Vệ Sinh Siêu Âm Toàn Diện', 'Bệnh Viện Phím', 'Khắc phục bàn phím bị đổ nước/cà phê, đứt mạch ngầm, bung chân socket hotswap.', 'Rửa keycap bằng bể sóng siêu âm và bảo dưỡng toàn bộ stabilizer.', 300000, 380000, 21, 99, 1520, 4.9, 250, '-21%', 1, NULL, NULL, NULL, NULL, NULL);
