INSERT INTO reviews (product_id, user_id, reviewer_name, avatar_text, rating, variant_info, comment, helpful_count, review_date) VALUES
                                                                                                                                     (1, 33, 'Nguyễn Minh Khôi', 'MK', 5, 'Phân loại: Silver / Brass plate', 'Kit hoàn thiện rất tốt, anodize đều màu, không có vết xước. Gasket êm, gõ nghe chắc chứ không vang.', 24, '20/09/2026'),
                                                                                                                                     (1, 34, 'Trần Hoàng Phúc', 'HP', 4, 'Phân loại: Black / PC plate', 'Chất lượng ổn trong tầm giá. PC plate mềm hơn brass nhiều, ai thích gõ êm thì chọn.', 18, '18/09/2026'),
                                                                                                                                     (2, 33, 'Nguyễn Minh Khôi', 'MK', 5, 'Phân loại: Bịch 70 nút', 'Switch Gateron Oil King mượt ngay từ nhà máy, âm trầm ấm cực kỳ đáng tiền.', 31, '02/10/2026'),
                                                                                                                                     (16, 35, 'Vũ Thành Đạt', 'TĐ', 5, 'Phân loại: Silver / WOBKEY', 'Rainy75 âm gõ mưa rơi đúng như lời đồn, pin 7000mAh dùng cả tháng chưa hết.', 42, '10/10/2026');
