                                                                                                                           (2, 'Lube cơ bản', 450000, '3–4 ngày làm việc', 'Lube housing + lò xo toàn bộ switch; Lắp ráp và test từng phím; Bảo hành 3 tháng', 0, 14, 'ACTIVE'),
                                                                                                                           (2, 'Full lube + tune', 750000, '5–7 ngày làm việc', 'Toàn bộ gói Lube cơ bản; Film switch (Deskeys/TX); Clip + lube + band-aid stabilizer; Tape mod & PE foam theo yêu cầu; Bảo hành 6 tháng', 1, 19, 'ACTIVE'),
                                                                                                                           (2, 'Premium — mod đầy đủ', 1250000, '7–10 ngày làm việc', 'Toàn bộ gói Full lube + tune; Force break mod, holee mod; Cân chỉnh âm thanh theo yêu cầu; Quay video test bàn giao; Bảo hành 12 tháng', 0, 5, 'ACTIVE'),
                                                                                                                           (1, 'Gói Build Tiêu Chuẩn KeebLab', 500000, '3–5 ngày làm việc', 'Lube switch Krytox 205g0; Cân chỉnh Stabilizer; Lắp ráp hoàn thiện & test keymap VIA', 1, 22, 'ACTIVE'),
                                                                                                                           (1, 'Gói Audiophile Custom', 950000, '5–7 ngày làm việc', 'Lube + Film toàn bộ switch; Tune TX/Staebies stab; Mod foam Poron + PET sheet; Quay soundtest 4K bàn giao', 0, 11, 'ACTIVE'),
                                                                                                                           (6, 'Gói Mod Thocky Monsgeek', 400000, '2–4 ngày làm việc', 'Lube switch & stab; Force break mod khử ping vỏ nhôm; Tape mod 3 lớp chuẩn âm trầm', 1, 16, 'ACTIVE'),
                                                                                                                           (7, 'Gói Sài Gòn Thock Signature', 800000, '4–6 ngày làm việc', 'Lube Krytox 205g0 + 105; Cắt foam Poron theo mạch; Cân chỉnh âm thanh từng hàng phím', 1, 18, 'ACTIVE'),
                                                                                                                           (8, 'Gói Rã Hàn & Mill-Max 3305', 950000, '5–7 ngày làm việc', 'Rã hàn mạch cũ bằng máy hút chân không; Hàn chân đồng Mill-Max hotswap; Vệ sinh siêu âm toàn mạch', 1, 9, 'ACTIVE');
