                                                                                                                                                                                                                                                                                                                      (1, 'KH-20261015-001', 1, 2, 1, 'Kit Tofu60 2.0 · Oil King ×70 · GMK Olivia · Full lube', 'Nguyễn Văn Anh', '0987654321', '123 Nguyễn Trãi, Quận 5, TP.HCM', 1, 2690000, 750000, 30000, 100000, 3370000, 'VNPAY-QR', 'PROCESSING', 60, 'Nhờ shop lube kỹ stab giúp mình nhé, ưu tiên âm trầm thocky.', 'Xưởng SwitchHouse đã xác nhận báo giá: Kit Tofu60 + gói Full lube + tune (750.000đ). Đang tiến hành tới công đoạn 4.', 7),
                                                                                                                                                                                                                                                                                                                      (2, 'KH-20261010-002', 1, 3, 7, 'Phân loại: Black & Pink ASA · ×1', 'Nguyễn Văn Anh', '0987654321', '123 Nguyễn Trãi, Quận 5, TP.HCM', 0, 690000, 0, 25000, 0, 715000, 'COD', 'COMPLETED', 100, 'Giao giờ hành chính.', 'Đơn hàng đã giao thành công.', 3),
                                                                                                                                                                                                                                                                                                                      (3, 'KH-284170', 33, 2, 4, 'Keychron Q1 Pro · Boba U4T ×84 · Gói Premium', 'Nguyễn Minh Khôi', '0938111222', 'Quận Bình Thạnh, TP.HCM', 1, 5890000, 1250000, 30000, 0, 7170000, 'VNPAY-QR', 'PENDING', 0, 'Em muốn tape mod + PE foam nếu shop làm được. Stab thì clip chân với band-aid giúp em.', NULL, 7),
                                                                                                                                                                                                                                                                                                                      (4, 'KH-284169', 35, 2, 16, 'Kit Rainy75 Pro · HMX Xinhai ×80 · Gói Full lube', 'Vũ Thành Đạt', '0905888777', 'Quận 1, TP.HCM', 1, 3130000, 750000, 30000, 0, 3910000, 'MoMo', 'PENDING', 0, 'Nhờ shop test kỹ từng socket hotswap và cân chỉnh kỹ phím Space giúp em.', NULL, 6),
                                                                                                                                                                                                                                                                                                                      (5, 'KH-284166', 34, 2, 6, 'Stabilizer Durock V2 PCB-mount · ×2', 'Trần Hoàng Phúc', '0977222333', 'Hải Châu, Đà Nẵng', 0, 840000, 0, 30000, 0, 870000, 'COD', 'SHIPPING', 100, '', 'Đã bàn giao cho đơn vị vận chuyển.', 3),
                                                                                                                                                                                                                                                                                                                      (6, 'KH-284140', 33, 2, 8, 'Kit Monsgeek M1W V3 · Akko Cream Yellow · Gói Lube cơ bản', 'Nguyễn Minh Khôi', '0938111222', 'Quận Bình Thạnh, TP.HCM', 1, 2470000, 450000, 30000, 0, 2950000, 'VNPAY-QR', 'COMPLETED', 100, 'Build êm để mang lên văn phòng gõ.', 'Đã hoàn tất bàn giao kèm video soundtest.', 5);
