INSERT INTO order_progress (order_id, step_number, step_title, step_desc, status, updated_time) VALUES
                                                                                                    (1, 1, 'Rã hàn & kiểm tra PCB', 'Đã đo thông mạch toàn bộ 61 socket hotswap trên Kit Tofu60 2.0. Tất cả socket và LED hoạt động hoàn hảo.', 'COMPLETED', '15/10 · 09:20'),
                                                                                                    (1, 2, 'Lube switch (70/70)', 'Lube Krytox 205g0 cho housing và GPL 105 cho lò xo, gắn film Deskeys cho toàn bộ 70 switch Oil King.', 'COMPLETED', '15/10 · 14:40'),
                                                                                                    (1, 3, 'Cân stabilizer', 'Clip + lube Durock V2 cho phím Space, Enter, Backspace, 2 Shift. Đã căn wire thẳng tắp, hết rattle.', 'COMPLETED', '16/10 · 10:05'),
                                                                                                    (1, 4, 'Lắp ráp & test toàn phím', 'Lắp switch, gắn keycap, test từng phím bằng phần mềm VIA và kiểm tra âm thanh.', 'IN_PROGRESS', 'Đang thực hiện'),
                                                                                                    (1, 5, 'Đóng gói & bàn giao vận chuyển', 'Quay video soundtest cuối, đóng thùng chống sốc bàn giao vận chuyển.', 'PENDING', 'Dự kiến 18/10');