DROP DATABASE IF EXISTS keebhub_db;
CREATE DATABASE keebhub_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE keebhub_db;

CREATE TABLE users (
                       id INT AUTO_INCREMENT PRIMARY KEY,
                       first_name VARCHAR(50) NOT NULL,
                       last_name VARCHAR(50) NOT NULL,
                       email VARCHAR(100) NOT NULL UNIQUE,
                       phone VARCHAR(20),
                       password VARCHAR(255) NOT NULL,
                       gender VARCHAR(10) DEFAULT 'Nam',
                       dob DATE,
                       avatar_text VARCHAR(5) DEFAULT 'KH',
                       role VARCHAR(20) DEFAULT 'CUSTOMER',
                       points INT DEFAULT 0,
                       is_verified TINYINT(1) DEFAULT 1,
                       status VARCHAR(20) DEFAULT 'ACTIVE',
                       created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE shops (
                       id INT AUTO_INCREMENT PRIMARY KEY,
                       owner_id INT UNIQUE,
                       shop_name VARCHAR(100) NOT NULL,
                       slug VARCHAR(100),
                       avatar_text VARCHAR(5),
                       avatar_color VARCHAR(20) DEFAULT '#1B64F2',
                       description TEXT,
                       address VARCHAR(255),
                       working_hours VARCHAR(100) DEFAULT '08:30 – 18:00, T2-T7',
                       is_verified TINYINT(1) DEFAULT 1,
                       is_workshop TINYINT(1) DEFAULT 1,
                       rating_avg DECIMAL(2,1) DEFAULT 4.9,
                       rating_count INT DEFAULT 0,
                       follower_count INT DEFAULT 0,
                       product_count INT DEFAULT 0,
                       response_rate INT DEFAULT 98,
                       response_time VARCHAR(50) DEFAULT 'trong 1 giờ',
                       on_time_rate DECIMAL(4,1) DEFAULT 96.5,
                       cancel_rate DECIMAL(4,1) DEFAULT 0.8,
                       return_rate DECIMAL(4,1) DEFAULT 0.5,
                       joined_date VARCHAR(20) DEFAULT '03/2021',
                       CONSTRAINT fk_shops_owner FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE categories (
                            id INT AUTO_INCREMENT PRIMARY KEY,
                            name VARCHAR(100) NOT NULL,
                            slug VARCHAR(100) NOT NULL,
                            icon VARCHAR(50),
                            product_count INT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE products (
                          id INT AUTO_INCREMENT PRIMARY KEY,
                          shop_id INT NOT NULL,
                          category_id INT NOT NULL,
                          sku VARCHAR(50),
                          name VARCHAR(255) NOT NULL,
                          brand VARCHAR(100),
                          short_desc TEXT,
                          description TEXT,
                          price DECIMAL(12,0) NOT NULL,
                          old_price DECIMAL(12,0) DEFAULT 0,
                          discount_percent INT DEFAULT 0,
                          stock INT DEFAULT 50,
                          sold_count INT DEFAULT 0,
                          rating_avg DECIMAL(2,1) DEFAULT 4.8,
                          rating_count INT DEFAULT 0,
                          badge VARCHAR(50),
                          support_custom TINYINT(1) DEFAULT 1,
                          switch_type VARCHAR(50),
                          actuation_force VARCHAR(50),
                          pin_type VARCHAR(20),
                          layout VARCHAR(50),
                          mount_type VARCHAR(50),
                          image_url VARCHAR(255),
                          status VARCHAR(20) DEFAULT 'ACTIVE',
                          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                          CONSTRAINT fk_products_shop FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE CASCADE,
                          CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE product_options (
                                 id INT AUTO_INCREMENT PRIMARY KEY,
                                 product_id INT NOT NULL,
                                 option_group VARCHAR(50) NOT NULL,
                                 option_name VARCHAR(100) NOT NULL,
                                 extra_price DECIMAL(12,0) DEFAULT 0,
                                 is_available TINYINT(1) DEFAULT 1,
                                 CONSTRAINT fk_options_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE product_specs (
                               id INT AUTO_INCREMENT PRIMARY KEY,
                               product_id INT NOT NULL,
                               spec_name VARCHAR(100) NOT NULL,
                               spec_value VARCHAR(255) NOT NULL,
                               display_order INT DEFAULT 1,
                               CONSTRAINT fk_specs_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE product_compatibilities (
                                         id INT AUTO_INCREMENT PRIMARY KEY,
                                         product_id INT NOT NULL,
                                         title VARCHAR(150) NOT NULL,
                                         description VARCHAR(255) NOT NULL,
                                         is_compatible TINYINT(1) DEFAULT 1,
                                         CONSTRAINT fk_compat_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE reviews (
                         id INT AUTO_INCREMENT PRIMARY KEY,
                         product_id INT NOT NULL,
                         user_id INT,
                         reviewer_name VARCHAR(100) NOT NULL,
                         avatar_text VARCHAR(5) DEFAULT 'KH',
                         rating INT DEFAULT 5,
                         variant_info VARCHAR(255),
                         comment TEXT,
                         helpful_count INT DEFAULT 0,
                         review_date VARCHAR(20),
                         created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                         CONSTRAINT fk_reviews_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE custom_services (
                                 id INT AUTO_INCREMENT PRIMARY KEY,
                                 shop_id INT NOT NULL,
                                 service_name VARCHAR(150) NOT NULL,
                                 price DECIMAL(12,0) NOT NULL,
                                 duration_text VARCHAR(50) DEFAULT '3-4 ngày làm việc',
                                 description TEXT,
                                 is_popular TINYINT(1) DEFAULT 0,
                                 sold_month INT DEFAULT 0,
                                 status VARCHAR(20) DEFAULT 'ACTIVE',
                                 CONSTRAINT fk_services_shop FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cart_items (
                            id INT AUTO_INCREMENT PRIMARY KEY,
                            user_id INT NOT NULL,
                            product_id INT NOT NULL,
                            quantity INT NOT NULL DEFAULT 1,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                            UNIQUE KEY user_product_unique (user_id, product_id),
                            CONSTRAINT fk_cart_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                            CONSTRAINT fk_cart_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE orders (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        order_code VARCHAR(30) NOT NULL UNIQUE,
                        user_id INT NOT NULL,
                        shop_id INT NOT NULL,
                        product_id INT DEFAULT 1,
                        variant_summary VARCHAR(255) DEFAULT 'Phân loại: Tiêu chuẩn · ×1',
                        receiver_name VARCHAR(100) NOT NULL,
                        receiver_phone VARCHAR(20) NOT NULL,
                        shipping_address VARCHAR(255) NOT NULL,
                        is_custom_order TINYINT(1) DEFAULT 0,
                        subtotal DECIMAL(12,0) NOT NULL,
                        custom_fee DECIMAL(12,0) DEFAULT 0,
                        shipping_fee DECIMAL(12,0) DEFAULT 0,
                        discount_amount DECIMAL(12,0) DEFAULT 0,
                        total_amount DECIMAL(12,0) NOT NULL,
                        payment_method VARCHAR(50) DEFAULT 'VNPAY-QR',
                        order_status VARCHAR(30) DEFAULT 'PENDING',
                        progress_percent INT DEFAULT 0,
                        customer_note TEXT,
                        shop_note TEXT,
                        committed_days INT DEFAULT 7,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id),
                        CONSTRAINT fk_orders_shop FOREIGN KEY (shop_id) REFERENCES shops(id)
) ENGINE=InnoDB;

CREATE TABLE order_items (
                             id INT AUTO_INCREMENT PRIMARY KEY,
                             order_id INT NOT NULL,
                             product_id INT NOT NULL,
                             product_name VARCHAR(255) NOT NULL,
                             quantity INT NOT NULL,
                             unit_price DECIMAL(12,0) NOT NULL,
                             line_total DECIMAL(12,0) NOT NULL,
                             created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                             CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
                             CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products(id)
) ENGINE=InnoDB;

CREATE TABLE order_progress (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                order_id INT NOT NULL,
                                step_number INT NOT NULL,
                                step_title VARCHAR(150) NOT NULL,
                                step_desc TEXT,
                                status VARCHAR(20) DEFAULT 'PENDING',
                                updated_time VARCHAR(50),
                                CONSTRAINT fk_progress_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB;

