-- Đồng bộ tự động số lượng sản phẩm thật (product_count) vào bảng categories và shops
UPDATE categories c SET product_count = (SELECT COUNT(*) FROM products p WHERE p.category_id = c.id);
UPDATE shops s SET product_count = (SELECT COUNT(*) FROM products p WHERE p.shop_id = s.id);

